export interface Order {
  readonly id: string;
  readonly items: ReadonlyArray<Item>;
}

export function addItem(order: Order, item: Item): Order {
  return { ...order, items: [...order.items, item] };   // copy, never mutate
}

const cfg = { host: "db", port: 5432 } as const;   // read-only and narrow

export function makeOrder(id: string, items: readonly Item[]): Readonly<Order> {
  return Object.freeze({ id, items: Object.freeze([...items]) as readonly Item[] });
}
